logger = logging.get_logger(__name__)


R_dict = {
    "7b": {
        2: {
            512: 452,
            384: 314,
            256: 176,
            128: 38,
        },
    },
}


class FastVQwen2_5_VLModel(Qwen2_5_VLModel):
    def __init__(self, config: Qwen2_5_VLConfig, visual_token_num: int):
        super().__init__(config)
        # transformers 4.52+ moved transformer layers into self.language_model
        # Create aliases so the forward() method (written for old structure) still works
        lm = self.language_model
        self.embed_tokens = lm.embed_tokens
        self.layers = lm.layers
        self.norm = lm.norm
        self.rotary_emb = lm.rotary_emb
        self._update_causal_mask = lm._update_causal_mask

        self.system_prompt_length = 15
        self.visual_token_length = 1296
        self.visual_token_num = 0
        self.visual_token_len = 0
        self.fastv_debug = True

        # num_hidden_layers lives on text_config in 4.52+
        n_layers = getattr(config, 'num_hidden_layers', None) or config.text_config.num_hidden_layers
        if n_layers == 28:
            self.scale = "7b"

        # FastV config
        self.K = 2
        self.R = R_dict[self.scale][self.K][visual_token_num]

    def _rotate_half(self, x: torch.Tensor) -> torch.Tensor:
        """Rotate last dimension by splitting heads into two halves."""
        x1 = x[..., : x.shape[-1] // 2]
        x2 = x[..., x.shape[-1] // 2 :]
        return torch.cat((-x2, x1), dim=-1)

    def _compute_visual_token_importance(
        self,
        hidden_states: torch.Tensor,
        decoder_layer: nn.Module,
        position_embeddings: Tuple[torch.Tensor, torch.Tensor],
        current_visual_length: int,
    ) -> torch.Tensor:
        """
        Estimate visual token importance using a lightweight attention probe.

        This avoids requesting full attention probabilities from FlashAttention,
        keeping memory usage linear in the number of visual tokens.
        """
        self_attn = decoder_layer.self_attn

        # Align with the layer's pre-attention normalization if available.
        attn_input = hidden_states
        input_layernorm = getattr(decoder_layer, "input_layernorm", None)
        if input_layernorm is not None:
            attn_input = input_layernorm(attn_input)

        bsz, seq_len, _ = attn_input.shape
        num_heads = self_attn.num_heads
        num_kv_heads = self_attn.num_key_value_heads
        head_dim = self_attn.head_dim

        if self.fastv_debug:
            print(f"    [_compute_visual_token_importance]")
            print(f"      Input: bsz={bsz}, seq_len={seq_len}, num_heads={num_heads}, head_dim={head_dim}")

        query_states = self_attn.q_proj(attn_input)
        key_states = self_attn.k_proj(attn_input)

        query_states = query_states.view(bsz, seq_len, num_heads, head_dim).transpose(1, 2)
        key_states = key_states.view(bsz, seq_len, num_kv_heads, head_dim).transpose(1, 2)

        if num_kv_heads != num_heads:
            num_groups = num_heads // num_kv_heads
            key_states = key_states.repeat_interleave(num_groups, dim=1)

        cos, sin = position_embeddings
        if self.fastv_debug:
            print(f"      Position embeddings: cos.shape={cos.shape}, sin.shape={sin.shape}")
        if cos.dim() == 3:
            cos = cos.unsqueeze(1)
            sin = sin.unsqueeze(1)
            if self.fastv_debug:
                print(f"      After unsqueeze: cos.shape={cos.shape}, sin.shape={sin.shape}")
        query_states = (query_states * cos) + (self._rotate_half(query_states) * sin)
        key_states = (key_states * cos) + (self._rotate_half(key_states) * sin)

        visual_start = self.system_prompt_length
        visual_end = visual_start + current_visual_length

        query_last = query_states[:, :, -1:, :]
        key_visual = key_states[:, :, visual_start:visual_end, :]

        attn_scores = torch.matmul(query_last, key_visual.transpose(-2, -1))
        attn_scores = attn_scores / math.sqrt(head_dim)

        attn_weights = F.softmax(attn_scores, dim=-1, dtype=torch.float32).to(query_states.dtype)
        visual_importance = attn_weights.mean(dim=1).squeeze(-2)  # [batch, visual_len]
        visual_importance = visual_importance.mean(dim=0)  # aggregate across batch
        return visual_importance

    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
    ) -> Union[Tuple, BaseModelOutputWithPast]:
        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        use_cache = use_cache if use_cache is not None else self.config.use_cache

        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if self.is_gradient_checkpointing and self.training:
            if use_cache:
                logger.warning_once(
                    "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`..."
                )
                use_cache = False

        # torch.jit.trace() doesn't support cache objects in the output
        if use_cache and past_key_values is None and not torch.jit.is_tracing():
            past_key_values = DynamicCache()

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if cache_position is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            cache_position = torch.arange(
                past_seen_tokens, past_seen_tokens + inputs_embeds.shape[1], device=inputs_embeds.device
            )

        # the hard coded `3` is for temporal, height and width.
        if position_ids is None:
            position_ids = cache_position.view(1, 1, -1).expand(3, inputs_embeds.shape[0], -1)
        elif position_ids.dim() == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)

        causal_mask = self._update_causal_mask(
            attention_mask, inputs_embeds, cache_position, past_key_values, output_attentions
        )

        hidden_states = inputs_embeds

        # create position embeddings to be shared across the decoder layers
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        # decoder layers
        all_hidden_states = () if output_hidden_states else None
        all_self_attns = () if output_attentions else None
        next_decoder_cache = None

        # FastV
        fastv_enabled = inputs_embeds.shape[1] > 1
        if fastv_enabled:
            current_visual_token_length = self.visual_token_length
            visual_token_accumulator = 0
            if self.fastv_debug:
                print("\n" + "="*80)
                print("[FastV Qwen2.5-VL DEBUG] Prefill Phase Start")
                print("="*80)
                print(f"  Sequence length: {inputs_embeds.shape[1]}")
                print(f"  System prompt length: {self.system_prompt_length}")
                print(f"  Initial visual tokens: {current_visual_token_length}")
                print(f"  Pruning layer K: {self.K}")
                print(f"  Target retention R: {self.R}")
                print(f"  Inputs_embeds shape: {inputs_embeds.shape}")
                print(f"  Position_ids shape: {position_ids.shape}")
                print(f"  Position_embeddings type: {type(position_embeddings)}")
                if isinstance(position_embeddings, (list, tuple)):
                    print(f"  Position_embeddings[0] shape: {position_embeddings[0].shape}")
                    print(f"  Position_embeddings[1] shape: {position_embeddings[1].shape}")
                print("="*80 + "\n")

        for decoder_layer in self.layers:
            if output_hidden_states:
                all_hidden_states += (hidden_states,)

            if fastv_enabled:
                visual_token_accumulator += current_visual_token_length

            if self.is_gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    decoder_layer.__call__,
                    hidden_states,
                    causal_mask,
                    position_ids,
                    past_key_values,
                    output_attentions,
                    use_cache,
                    cache_position,
                    position_embeddings,
                )
            else:
                ####################################################################################################
                # Visual Token Pruning
                if fastv_enabled:
                    layer_idx = decoder_layer.self_attn.layer_idx + 1

                    if layer_idx == self.K and current_visual_token_length > self.R:
                        device = hidden_states.device
                        prev_visual_length = current_visual_token_length
                        if self.fastv_debug:
                            print(f"\n[FastV PRUNING] Layer {layer_idx}")
                            print(f"  Before: {prev_visual_length} visual tokens → Target: {self.R}")
                            print(f"  Hidden states shape: {hidden_states.shape}")
                            print(f"  Position_ids shape: {position_ids.shape}")
                            print(f"  Visual start: {self.system_prompt_length}")
                            print(f"  Visual end: {self.system_prompt_length + prev_visual_length}")

                        visual_importance = self._compute_visual_token_importance(
                            hidden_states, decoder_layer, position_embeddings, prev_visual_length
                        )

                        if self.fastv_debug:
                            print(f"  Visual importance shape: {visual_importance.shape}")
                            print(f"  Visual importance stats: min={visual_importance.min():.6f}, "
                                  f"max={visual_importance.max():.6f}, mean={visual_importance.mean():.6f}")

                        keep = min(self.R, visual_importance.shape[0])
                        if keep > 0:
                            visual_token_indices = visual_importance.topk(keep).indices
                            visual_token_indices = torch.sort(visual_token_indices).values
                        else:
                            visual_token_indices = visual_importance.new_empty((0,), dtype=torch.long)

                        layer_outputs = decoder_layer(
                            hidden_states,
                            attention_mask=causal_mask,
                            position_ids=position_ids,
                            past_key_value=past_key_values,
                            output_attentions=output_attentions,
                            use_cache=use_cache,
                            cache_position=cache_position,
                            position_embeddings=position_embeddings,
                        )
                        hidden_states = layer_outputs[0]

                        retain_token_indices = torch.cat(
                            (
                                torch.arange(self.system_prompt_length, device=device),
                                visual_token_indices + self.system_prompt_length,
                                torch.arange(
                                    self.system_prompt_length + prev_visual_length,
                                    hidden_states.shape[1],
                                    device=device,
                                ),
                            )
                        )

                        hidden_states = hidden_states[:, retain_token_indices].contiguous()
                        position_ids = position_ids[:, :, retain_token_indices]
                        cache_position = cache_position[: retain_token_indices.shape[0]]
                        position_embeddings = [pos_emb[:, :, retain_token_indices] for pos_emb in position_embeddings]

                        causal_mask = self._update_causal_mask(
                            None, hidden_states, cache_position, past_key_values, output_attentions
                        )

                        current_visual_token_length = keep
                        if self.fastv_debug:
                            print(f"  After pruning:")
                            print(f"    Hidden states shape: {hidden_states.shape}")
                            print(f"    Position_ids shape: {position_ids.shape}")
                            print(f"    Retained {keep} visual tokens")
                            print(f"    System prompt preserved: {self.system_prompt_length} tokens")
                            print(f"    Total sequence length: {hidden_states.shape[1]}")
                        layer_outputs = (hidden_states, layer_outputs[-1])
                    else:
                        if self.fastv_debug and layer_idx == self.K and current_visual_token_length <= self.R:
                            print(
                                f"[FastV Stage] Layer {layer_idx}: skip pruning "
                                f"(current {current_visual_token_length} ≤ target {self.R})",
                                flush=True,
                            )
                        layer_outputs = decoder_layer(
                            hidden_states,
                            attention_mask=causal_mask,
                            position_ids=position_ids,
                            past_key_value=past_key_values,
                            output_attentions=output_attentions,
                            use_cache=use_cache,
                            cache_position=cache_position,
                            position_embeddings=position_embeddings,
                        )
                ####################################################################################################
                else:
                    layer_outputs = decoder_layer(
                        hidden_states,
                        attention_mask=causal_mask,
                        position_ids=position_ids,
                        past_key_value=past_key_values,
                        output_attentions=output_attentions,
                        use_cache=use_cache,
                        cache_position=cache_position,
                        position_embeddings=position_embeddings,
                    )

            hidden_states = layer_outputs[0]

            if use_cache:
                next_decoder_cache = layer_outputs[2 if output_attentions else 1]

            if output_attentions:
                all_self_attns += (layer_outputs[1],)

        hidden_states = self.norm(hidden_states)

        # FastV
        if fastv_enabled:
            average_tokens = visual_token_accumulator / len(self.layers)
            self.visual_token_num = average_tokens
            self.visual_token_len = average_tokens
            if self.fastv_debug:
                print(
                    f"[FastV DEBUG] Visual token average across layers: {average_tokens:.2f} "
                    f"(target {self.R})",
                    flush=True,
                )

        # add hidden states from the last decoder layer
        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        next_cache = next_decoder_cache if use_cache else None

        if not return_dict:
            return tuple(v for v in [hidden_states, next_cache, all_hidden_states, all_self_attns] if v is not None)
        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=next_cache,
            hidden_states=all_hidden_states,
            attentions=all_self_attns,
        )
